%% ================================================
%  MATLAB: 用 ECB Nowcasting Toolbox 做 GDP nowcast
%  安装：https://github.com/european-central-bank/Nowcasting
% =================================================
clear; clc;

% ---- 1. 读入混频数据（第一列为日期，其余为指标；季度 GDP 行内留空即缺失）----
% 数据列顺序建议：月度硬指标 -> 月度软指标 -> 金融指标 -> 季度 GDP
[data, dates] = xlsread('mixed_data.xlsx');   % data(T,N), 缺失用 NaN
series_names  = {'IndProd','Retail','PMI_Hc','PMI_Svc','CPI','FedFunds','GDPq'};

% ---- 2. 参数设定 ----
Spec.nfactors      = 2;          % 因子个数
Spec.lag_factor    = 1;          % 因子 VAR 滞后
Spec.blocks        = [1 1 1 1 2 2 0];  % 各变量归属块（0=不属块）
Spec.lag_turn      = 1;
Spec.start_year    = 1995;
Spec.start_quarter = 1;
Spec.end_year      = 2024;
Spec.end_quarter   = 1;
Spec.savehist      = 1;

% ---- 3. 估计 DFM（EM 算法，自动处理 NaN 锯齿边）----
Spec = nowcast_config(Spec, series_names);
[Res] = nowcast_estimate(data, dates, Spec);

% ---- 4. 滚动 nowcast：每个新数据点重估一次 ----
[Nowcast] = nowcast_recursive(data, dates, Spec, Res);

% ---- 5. 绘制 nowcast 演进（news 曲线）----
figure;
plot(Nowcast.dates, Nowcast.gdp_nowcast, '-o'); hold on;
plot(Nowcast.dates, Nowcast.gdp_real, 'r--');
legend('Nowcast','Realized GDP');
title('GDP Nowcast 随实时数据流更新');

% ---- 6. News 分解：每条新数据对 nowcast 的边际贡献 ----
% 见 Res.news / Res.contribution：回答"是哪条数据把 nowcast 拉高了 0.1pp"

% ==============================================================
% TVP-VAR 估计核心骨架（Primiceri 2005 简化版）
% 生产环境请直接使用:
%   - Gary Koop & Dimitris Korobilis 的 TVP-VAR 工具箱
%     (https://sites.google.com/site/garykoop/)
%   - Primiceri 个人主页提供的 replication code
% 本文件只演示"如何组织数据 + 调用 FFBS + 保存后验"
% ==============================================================
clear; clc; rng(2024);

% ---------- 0. 读数据：n x T ----------
% y 三列: [inflation, unemployment, interest_rate]
load us_macro.mat;
y = us_macro;
[T, n] = size(y);
p = 2;                       % VAR 滞后阶数
m = n*(n*p + 1);             % beta_t 的维度

% ---------- 1. 堆叠 VAR 右侧 ----------
Y = y(p+1:end, :);
[T2, ~] = size(Y);
X = zeros(T2, m);
for t = 1:T2
    xt = 1;
    for lag = 1:p
        xt = [xt, y(p+t-lag, :)];
    end
    X(t,:) = kron(eye(n), xt);
end

% ---------- 2. 先验（Primiceri 2005 第 4 节） ----------
B0_hat  = (X'*X)\X'*Y(:);        % 用全样本 OLS 做初值
beta_0  = zeros(m,1);
Vbeta_0= 4*eye(m);               % 扩散先验
s2      = 4;                     % 超参数尺度
Q       = (s2+1)*eye(m)*0.01;    % 状态协方差初值

% ---------- 3. MCMC 主循环（示意 5000 次） ----------
nrep = 5000; nburn = 2000;
beta_draws = zeros(nrep, T2, m);
for irep = 1:nrep
    % (a) FFBS 抽 beta_t（给定 A, Sigma）
    %   beta_t 状态方程: beta_t = beta_{t-1} + u_t, Var=Q
    %   观测方程: Y = X*beta + A^-1*Sigma*eps
    beta_draws(irep,:,:) = FFBS_linear(Y, X, Q, beta_0, Vbeta_0);

    % (b) 抽 A_t（下三角同期结构）
    % A_draws(irep,:,:) = FFBS_A(...);

    % (c) 抽 Sigma_t（随机波动率，KSC 1998 mixture）
    % Sigma_draws(irep,:,:) = KSC_sv(Y, beta_draws(irep,:,:));

    % (d) 抽超参数 Q（Inverse-Wishart 后验）
    % Q = iwishrnd(...)

    if mod(irep,500)==0
        fprintf('MCMC iteration %d / %d\n', irep, nrep);
    end
end

% ---------- 4. 后处理：剔除 burn-in ----------
post_beta = beta_draws(nburn+1:end,:,:);
% 平均时变系数、后验分位数
beta_med = median(post_beta, [1 3]);

% ---------- 5. 计算时变脉冲响应 ----------
% 在每个时点 t 用后验 beta_t, A_t, Sigma_t 构造 VAR companion form,
% 向前迭代 h=0..20, 得到 IRF(t, h, shock)
